serde_boundary_tests:
use tfqm_category_theory::errors::ArithmosError;
use tfqm_category_theory::functor::full_functor::{
    FullFunctor, FullnessWitness, LabeledMorphism,
};

fn populated() -> FullFunctor {
    let image = LabeledMorphism::new("Fa", "Fb", "g");
    FullFunctor::on_functor("full", "F")
        .with_obligation(image.clone())
        .with_witness(FullnessWitness::new(LabeledMorphism::new("a", "b", "f"), image))
}

#[test]
fn legacy_serialized_record_is_explicitly_vacuous() {
    let value: FullFunctor = serde_json::from_str(
        r#"{"label":"full","functor_ref":"F","notes":[]}"#
    ).unwrap();
    assert!(value.is_vacuous());
    assert!(value.validated().is_ok());
}

#[test]
fn populated_record_roundtrips_without_changing_witnesses() {
    let value = populated().with_note("");
    let raw: FullFunctor = serde_json::from_str(&serde_json::to_string(&value).unwrap()).unwrap();
    assert_eq!(raw.validated().unwrap(), value);
}

#[test]
fn deserialized_uncovered_obligation_is_refused_by_owned_admission() {
    let mut value = serde_json::to_value(populated()).unwrap();
    value["witnesses"] = serde_json::json!([]);
    let raw: FullFunctor = serde_json::from_value(value).unwrap();
    assert_eq!(raw.validated(), Err(ArithmosError::InvalidShape(
        "obligation g : Fa -> Fb has no witness".into()
    )));
}

#[test]
fn deserialized_blank_label_is_refused_by_owned_admission() {
    let mut value = serde_json::to_value(populated()).unwrap();
    value["label"] = serde_json::json!(" \t");
    let raw: FullFunctor = serde_json::from_value(value).unwrap();
    assert_eq!(raw.validated(), Err(ArithmosError::InvalidShape("empty label".into())));
}
